import {Q} from './reading.mjs';
const C=(script,question,answer,wrongs,next,action,alternatives)=>({script,qs:[Q(question,answer,...wrongs,'The conversation directly supports this answer; the other choices change the reason or circumstance.'),Q(next,action,...alternatives,'The speakers’ final plan supports this choice.','inference')]});
export const conversations=[
C(`Woman: I booked a scanner for the old maps, but the glass is smaller than the largest sheet.\nMan: The archive has an overhead camera. It photographs large documents without folding them. You’ll need staff supervision, though.\nWoman: That would be better than joining several scans. Can I use it today?\nMan: The archive assistant returns at two. I’ll ask her to reserve a supervised slot.\nWoman: Thanks. I’ll keep the map flat until then.`, 'What problem does the woman have?','The document is too large for the available scanner',['She cannot locate the map','The scanner has stopped working','She has already folded the document'],'What will the man probably do?','Arrange help from archive staff',['Repair the scanner himself','Join several scans into one image','Move the camera to the library']),
C(`Man: Our survey team has plenty of volunteers for Saturday, but nobody has checked whether the stream path is open.\nWoman: It was closed after the storm. The parks office said they’d inspect the footbridge this morning.\nMan: Then sending everyone there could waste the whole trip.\nWoman: I’ll call the office after lunch. If the path stays closed, we can use the upstream access by the playing field.\nMan: Good. Let’s wait for that answer before messaging the group.`, 'Why are the speakers delaying a message to volunteers?','They need to confirm access to the survey site',['They have too few volunteers','They have changed the survey date','They have lost the volunteers’ contact details'],'What will the woman do next?','Contact the office responsible for the path',['Inspect the bridge by herself','Cancel the survey immediately','Meet the volunteers at the closed gate']),
C(`Woman: I thought my display label was clear, but visitors keep asking whether this is the original bowl.\nMan: You explain its history in the first paragraph. The fact that it’s a replica is near the bottom.\nWoman: So people may stop reading before they reach that part.\nMan: Exactly. Why not identify it as a replica in the first line and explain why we use one?\nWoman: I’ll revise the opening, then watch whether the same question comes up tomorrow.`, 'What does the man think is causing confusion?','Important information appears too late in the label',['The bowl is displayed upside down','The label describes the wrong historical period','Visitors cannot see the display'],'How will the woman respond to the suggestion?','Revise the label and observe visitors again',['Replace the bowl with another replica','Remove all historical information','Ask visitors to stop asking questions']),
C(`Man: I can help classify the donated photographs, but I don’t recognize many of the buildings.\nWoman: The date is written on the back of some prints. We also have a folder of old street names.\nMan: Would it be better if I guessed and you checked afterward?\nWoman: Please mark uncertain locations as unknown instead. We can ask residents at the history event.\nMan: All right. I’ll record what we can actually identify and keep the uncertain ones separate.`, 'What advice does the woman give?','Avoid treating guesses as established identifications',['Write modern dates on the photographs','Discard images of unfamiliar buildings','Ask residents to donate only labeled prints'],'What will the man do?','Separate photographs with uncertain locations',['Rename streets in the reference folder','Identify every building from memory','Cancel the community history event']),
C(`Woman: My project partner wants us to include every chart we made in our presentation.\nMan: How much time do you have?\nWoman: Eight minutes, including questions. Just explaining the first six charts takes that long.\nMan: Could you choose the two that answer your research question and keep the rest for questions?\nWoman: That would give the audience a clearer argument. I’ll suggest putting the extra charts in an appendix.\nMan: Then practice once together before making a final cut.`, 'What is the woman concerned about?','The amount of material exceeds the presentation time',['Her partner has not made any charts','The audience has already seen the results','Questions are not permitted after the talk'],'What change will she propose?','Keep the most relevant charts in the main presentation',['Extend the official presentation slot','Remove the research question','Explain every chart more quickly']),
C(`Man: The seed trays look dry, but the soil underneath is still wet. Should I water them again?\nWoman: Not yet. The top dries before the deeper layer. Too much water could damage the young roots.\nMan: I was following the timetable on the greenhouse wall.\nWoman: That schedule is for the larger pots. These trays need checking individually. Let’s label them so the next volunteer knows.\nMan: I’ll make a note about checking below the surface.`, 'Why does the woman advise against watering immediately?','The deeper soil already contains enough moisture',['The watering equipment is broken','The plants have no roots yet','All trays must remain completely dry'],'What will the man most likely record?','Instructions specific to the seed trays',['A request to remove the greenhouse schedule','The date for replacing all larger pots','A warning not to inspect the soil']),
C(`Woman: My interviewee agreed to be recorded, but now she wants one personal story removed.\nMan: Have you edited the public version yet?\nWoman: No, I was going to upload the whole recording tonight.\nMan: Then first confirm exactly which section she means. Our project agreement lets participants withdraw material before publication.\nWoman: I’ll send her the time markers and wait for confirmation. The edited version can go online afterward.\nMan: Keep a record of the permission change too.`, 'Why will publication be delayed?','The participant has requested removal of some material',['The website cannot accept audio files','The interview has not yet taken place','The project agreement forbids all recording'],'What will the woman do before editing?','Confirm the specific section to remove',['Upload an unedited backup publicly','Ask another interviewee to replace the story','Delete every interview in the project']),
C(`Man: I signed up for the tree survey, but I’ve never identified a tree from its bark.\nWoman: Neither had I last year. We work in pairs, and the coordinator gives us a short guide.\nMan: So I won’t be expected to name everything immediately?\nWoman: No. Record the features you see, then check uncertain examples with an experienced volunteer.\nMan: That sounds manageable. I’ll bring my notebook and join the training at nine.`, 'What reassurance does the woman offer?','New volunteers receive guidance and can ask for help',['Only experts are permitted to collect data','The survey does not involve identifying trees','Every tree has already been labeled'],'What does the man decide?','Attend the introductory training',['Withdraw from the survey','Memorize every species before arriving','Work alone instead of in a pair']),
C(`Woman: The repair café can use my sewing machine, but transporting it on the bus will be awkward.\nMan: We’re collecting donated equipment in the university van Friday afternoon.\nWoman: Would my machine count? I’m lending it rather than donating it.\nMan: That’s fine. We can collect loans too, provided you label the case and arrange a return time.\nWoman: I’ll add my contact details and book collection for Friday.\nMan: Put its instructions inside the case as well.`, 'What problem is the woman trying to solve?','Getting borrowed equipment to an event',['Finding a buyer for a sewing machine','Learning how to repair a bus','Replacing a machine that has been donated'],'What will she do?','Arrange collection and identify the machine as a loan',['Give the machine away permanently','Carry the machine on the bus anyway','Cancel the repair event']),
C(`Man: The sound level in our recording changes halfway through. Can the software fix it?\nWoman: It can adjust volume, but it can’t remove all the echo. Did you change rooms?\nMan: Yes, the first room was booked for a seminar.\nWoman: The empty room probably caused the echo. Could the speaker record that short section again in the original space?\nMan: She’s available tomorrow. I’ll ask before trying to repair the whole file digitally.`, 'What probably caused the change in sound?','Part of the recording was made in a different room',['The speaker changed the interview topic','The microphone was replaced by software','The seminar was recorded over the interview'],'What will the man try first?','Arrange a new recording of the affected section',['Delete the first half of the interview','Increase the volume of the entire file','Book an even larger empty room']),
C(`Woman: The bus-stop tree locations look good on the map, but there’s a water pipe beneath one of them.\nMan: Then we can’t just send the planting list to the volunteers.\nWoman: Right. The grounds team needs to approve the final positions.\nMan: Could we shift that tree a little toward the bench?\nWoman: Possibly, but the wheelchair route must stay clear. I’ll ask the team to mark a safe spot on site.`, 'Why must the planting plan be checked?','Underground infrastructure may interfere with a proposed location',['Volunteers have refused to follow the map','The bus stop is no longer in use','All trees have already been planted'],'What will the woman request?','A site check to identify an appropriate planting position',['Permission to block the wheelchair route','Removal of the bench immediately','A larger volunteer group before any review']),
C(`Man: I borrowed the portable recorder, but its memory is almost full.\nWoman: Don’t erase the existing files. Another student may not have copied them yet.\nMan: I need it for an interview this afternoon.\nWoman: Bring it to the media desk. They can lend you a blank card and contact the previous borrower.\nMan: Good. I’ll do that now instead of trying to decide which files matter.\nWoman: Remember to test the replacement card before leaving.`, 'What does the woman warn against?','Deleting recordings that may belong to another borrower',['Testing a blank memory card','Contacting the media desk','Using a recorder for interviews'],'What will the man do next?','Ask the media desk for a replacement memory card',['Cancel the interview without checking','Erase the oldest files himself','Return the recorder after the interview only']),
C(`Woman: Our neighborhood walk has forty registrations, but the guide can take only twenty people at a time.\nMan: Could we repeat the walk later the same day?\nWoman: She’s free after three. The exhibition closes at four, though.\nMan: Let the later group see the exhibition first, then take the walk.\nWoman: That solves both problems. I’ll offer two departure times and explain the different order.\nMan: Ask people to confirm their choice rather than assuming an even split.`, 'What difficulty are the speakers addressing?','More people registered than the guide can lead at once',['The exhibition has received no visitors','The guide is unavailable all afternoon','Both activities must happen in a single room'],'What will the woman offer?','Two walking groups with different activity sequences',['A single larger group without a guide','A walk after the exhibition has closed for everyone','Only a refund for every registrant']),
C(`Man: The posters say the repair workshop is free, but someone was asked to pay for a new cable.\nWoman: Instruction and tool use are free. Replacement parts aren’t included.\nMan: The poster doesn’t make that distinction very obvious.\nWoman: You’re right. We should put the parts policy beside the registration link.\nMan: I’ll revise the digital version today. Can you explain it at the desk until the printed copies are replaced?\nWoman: Certainly.`, 'What information needs to be clearer?','Free participation does not include replacement parts',['The workshop charges for borrowing every tool','Only paid members may register','All cables are supplied at no cost'],'What will the man change?','The online poster’s explanation of costs',['The amount charged for instruction','The location of the workshop','The rule allowing students to use tools']),
C(`Woman: I can’t find the image I used in my draft article. The filename is just a string of numbers.\nMan: Did you record the source when you downloaded it?\nWoman: Only the website address, not the photographer’s name or license.\nMan: Check the image page before submitting. Being able to download a picture doesn’t mean we can republish it.\nWoman: I’ll trace the source and use a different image if permission isn’t clear.`, 'What concern does the man raise?','The image may not be authorized for republication',['The article has too many numerical results','The photographer has already edited the draft','Downloaded images cannot be viewed in documents'],'What does the woman plan to do?','Verify permission before deciding whether to use the image',['Publish the image without a credit','Remove every illustration from the journal','Rename the file and assume that solves the problem']),
C(`Man: My lab partner put both sets of samples in identical boxes. Now I’m not sure which is the control group.\nWoman: Are the individual labels still attached?\nMan: Yes, they have the collection times.\nWoman: The shared log should connect those times with the groups. Check that before moving anything.\nMan: If the log confirms it, I’ll label the boxes clearly and ask my partner to verify the change.\nWoman: Good. Don’t rely on memory alone.`, 'What problem has arisen?','The sample groups are not clearly distinguished on their boxes',['All sample labels have fallen off','The experiment has no comparison group','The collection times were never recorded'],'What will the man consult?','The shared collection log',['A list of future laboratory bookings','The labels on unrelated equipment','His memory as the only source']),
C(`Woman: The loan desk says the field camera is due back at noon, but our bus returns at one.\nMan: Did you ask about extending the loan?\nWoman: Someone else has reserved it for the afternoon.\nMan: I’m cycling back before lunch. If you finish the photographs early, I could return it for you.\nWoman: That would help. I’ll complete that part of the survey first and meet you by the gate at eleven.`, 'Why is an extension difficult?','Another borrower needs the camera later that day',['The desk closes for the entire afternoon','The camera has stopped taking photographs','The survey bus will not return that day'],'How will the speakers solve the problem?','The man will take the camera back before the group returns',['They will ignore the return deadline','The woman will cancel all survey photographs','They will lend the camera directly to the next borrower']),
C(`Man: I’ve cut the podcast down to ten minutes, but the explanation of the experiment no longer makes sense.\nWoman: Which part did you remove?\nMan: The comparison between the two groups. It sounded repetitive.\nWoman: Listeners need that comparison to understand the conclusion. Could you shorten the introduction instead?\nMan: Yes, the welcome section is longer than necessary. I’ll restore the comparison and trim that opening.`, 'Why does the woman want a removed section restored?','It supplies evidence needed to understand the conclusion',['It includes the names of all the guests','It makes the introduction more entertaining','It explains how to download the podcast'],'What will the man shorten instead?','The introductory welcome',['The comparison between groups','The experiment’s central conclusion','Every explanation of the research method']),
C(`Woman: We planned to interview residents outside the market, but the forecast says heavy rain.\nMan: The community hall is available, although people won’t pass it naturally on their way home.\nWoman: Then moving there could change who participates.\nMan: True. We could keep the same invitations and offer another outdoor date as well.\nWoman: Let’s explain both options to the coordinator before changing the plan. I don’t want our sample to become less representative without us noticing.`, 'What concerns the woman about moving the interviews?','The change may affect which residents take part',['The hall has no recording equipment','The market will permanently close','Every resident has already declined'],'What will they do before changing arrangements?','Discuss the possible effects with the coordinator',['Select only residents who live beside the hall','Assume the venue makes no difference','Publish the incomplete results immediately']),
C(`Man: I want to join the oral-history project, but my accent might be a problem when interviewing people.\nWoman: The coordinator isn’t looking for one particular accent. Clear questions and careful listening matter more.\nMan: I can practice those. Is there training?\nWoman: Yes. We work in pairs and review a short practice recording together.\nMan: Then I’ll sign up for the training rather than deciding in advance that I can’t do it.`, 'What does the woman emphasize?','Effective interviewing depends on communication rather than a particular accent',['Every interviewer must sound exactly like the coordinator','No practice is offered before interviews','Interviewers should avoid listening to their recordings'],'What will the man do?','Attend the project training',['Withdraw because of his accent','Interview residents without preparing','Ask someone else to answer all questions for him']),
C(`Woman: The workshop room has twenty chairs, but only twelve places at tables.\nMan: For a lecture, that would be fine. People will actually be assembling models, though.\nWoman: So twenty registrations would be too many.\nMan: Unless we run two sessions. The instructor is available in the morning and afternoon.\nWoman: I’ll set up two smaller groups. We should tell people which session they’re assigned to before they arrive.`, 'Why is the chair count misleading?','Participants also need working space at tables',['Some chairs belong to another building','The workshop has become a lecture','The instructor will not attend'],'What arrangement will the woman make?','Two sessions with smaller groups',['One session with extra standing places','A lecture without model assembly','Cancellation of the afternoon availability']),
C(`Man: Our survey says that eighty percent of respondents like the new library hours. That sounds convincing.\nWoman: How did you reach them?\nMan: We asked people leaving the library just before closing.\nWoman: That may miss students who can’t use the current hours at all.\nMan: Good point. We should send the survey to a wider student list before presenting it as everyone’s opinion.\nWoman: And explain how the first responses were collected.`, 'What limitation does the woman identify?','The survey may exclude people unable to use the current hours',['The questions ask about too many library services','The survey includes only library staff','The results show that nobody likes the hours'],'What will the man do?','Seek responses from a broader group',['Delete the original responses without explanation','Report the result as a complete census','Shorten the opening hours himself']),
C(`Woman: The archive boxes arrived, but the supplier sent the smaller size.\nMan: Can we use them for the letters and keep the large maps somewhere else temporarily?\nWoman: The letters fit, but I don’t want to leave the maps unprotected.\nMan: We have flat storage folders in the conservation room. I’ll check whether some are available while you contact the supplier.\nWoman: Thanks. Then we can protect everything without folding the maps.`, 'Why can’t the new boxes solve the whole storage problem?','Some documents are too large for them',['The letters have already been discarded','The boxes cannot be opened','The maps must be rolled before storage'],'What will the man check?','Whether suitable flat folders are available',['Whether the supplier has received payment','Whether letters can be cut to size','Whether the maps can be folded safely']),
C(`Man: My rehearsal recording sounds rushed, even though I spoke within the time limit.\nWoman: You move straight from one example to the next. A brief pause could help listeners follow the structure.\nMan: Wouldn’t that make the talk too long?\nWoman: Not if you remove the repeated explanation at the end. You can use the saved time for clearer transitions.\nMan: I’ll try that and record another rehearsal rather than simply speaking faster.`, 'What does the woman suggest is missing?','Pauses that make the structure easier to follow',['More examples of exactly the same point','A longer statement of the time limit','A faster delivery of the conclusion'],'What will the man change?','Remove repetition and use clearer transitions',['Increase his speaking speed throughout','Abandon rehearsal recordings','Add several new examples without cutting anything']),
C(`Woman: The community garden sign-up sheet has names but no contact details.\nMan: We avoided collecting more information than we needed.\nWoman: That makes sense, but how will we tell people if Saturday’s session is cancelled?\nMan: We could ask them to join an optional announcement list. The gardening sheet itself wouldn’t need email addresses.\nWoman: Good. I’ll add that invitation and explain it’s only for schedule updates.`, 'What problem does the woman identify?','There is no direct way to notify volunteers of a cancellation',['Nobody has volunteered for the garden','The sheet contains too much personal information','The garden does not open on Saturdays'],'What solution do they choose?','Offer a separate optional announcement list',['Publish all volunteers’ contact details','Require a postal address for every session','Stop announcing schedule changes']),
C(`Man: I reserved the quiet booth to practice my presentation, but someone is using it for an online exam.\nWoman: Check whether your booking starts now. There was a change to the timetable this morning.\nMan: You’re right; my confirmation says three, not two.\nWoman: The seminar room is empty until then, though it isn’t soundproof.\nMan: I’ll rehearse my slides there first and move to the booth for the recording at three.`, 'Why is the booth unavailable to the man now?','His reservation begins later than he thought',['His reservation was permanently cancelled','The booth has no microphone','The other student ignored the timetable'],'How will he use the waiting time?','Practice the slides in another room',['Interrupt the online exam','Cancel his presentation','Record a loud rehearsal beside the booth']),
C(`Woman: I can lend the club my projector, but the hall’s screen is on the side wall.\nMan: Then the seats should face that way.\nWoman: We’d have to keep the exit route clear, and the current plan puts a row right across it.\nMan: Let’s ask the hall manager to approve a revised seating plan before we move anything.\nWoman: Agreed. Better to solve the layout now than when people are arriving.`, 'What concern changes the seating discussion?','The planned arrangement could obstruct an exit route',['The projector is too expensive to borrow','The hall has no screen at all','The club has sold no tickets'],'What will the speakers do first?','Get approval for a revised arrangement',['Move chairs across the exit','Cancel the hall reservation immediately','Ask visitors to stand throughout the event']),
C(`Man: My notes say the interview was on the twelfth, but the audio filename says the thirteenth.\nWoman: The recorder’s date was wrong that week. Do you have the appointment email?\nMan: Yes, it confirms the twelfth.\nWoman: Use that as the date and add a note explaining the filename discrepancy. Don’t rename the original without a record.\nMan: I’ll document the correction in the project log.`, 'What explains the inconsistent dates?','The recorder’s date setting was incorrect',['Two separate interviews took place','The appointment email was sent late','The interviewee changed the topic'],'What will the man do?','Record the correction and its supporting evidence',['Change the appointment email','Delete the original recording','Use the filename without further explanation']),
C(`Woman: The lab demonstration needs ice, but the department freezer is being defrosted.\nMan: The café can supply some in the morning, provided we collect it before they open.\nWoman: I have an early lecture. Could you pick it up?\nMan: Yes, if you leave the insulated container at reception tonight.\nWoman: I’ll label it with the lab number and leave it there before six.\nMan: Then I’ll bring the ice straight to the demonstration room.`, 'Why do the speakers need another source of ice?','The usual freezer is temporarily unavailable',['The demonstration has moved to the café','The department no longer permits ice','The laboratory container has been lost'],'What must the woman do?','Leave the insulated container at reception',['Collect ice after the café opens','Cancel her early lecture','Bring the department freezer to the café']),
C(`Man: The professor asked for an anonymous summary of the workshop feedback, but some comments mention students by name.\nWoman: Remove identifying details before you share it. Keep the points about the workshop itself.\nMan: What if removing a name makes a sentence hard to follow?\nWoman: Paraphrase that part without changing its meaning, and note that the comments were anonymized.\nMan: I’ll do that before sending the summary to the class.`, 'What requirement is the man trying to meet?','Protecting the identities of people mentioned in feedback',['Including every participant’s name in a report','Changing negative comments into positive ones','Publishing the original feedback without editing'],'How will he handle unclear comments?','Paraphrase identifying parts while preserving their meaning',['Invent details to complete them','Delete every critical comment','Ask the class to identify each writer']),
C(`Woman: I found an inexpensive room for our discussion group, but it’s upstairs and there’s no lift.\nMan: One member uses a wheelchair, so that won’t work.\nWoman: The accessible room costs more unless a department sponsors the booking.\nMan: Our adviser said she could support student-led events. Let’s ask her about sponsorship before choosing another building.\nWoman: I’ll send her the details and explain the access issue.`, 'Why is the inexpensive room unsuitable?','It is not accessible to every group member',['It lacks enough discussion topics','It is already sponsored by a department','It is outside the university'],'What will the woman request?','Help obtaining the accessible room',['Permission to exclude a member','Cancellation of all group discussions','Installation of a lift before the meeting']),
C(`Man: Our camera count shows fewer animals this week. Should we report a population decline?\nWoman: First check whether every camera was operating. One battery failed during the cold nights.\nMan: I hadn’t compared the operating hours.\nWoman: A shorter recording period could explain some of the difference. We should describe that limitation before interpreting the totals.\nMan: I’ll calculate the active hours for each camera and revise the comparison.`, 'Why does the woman question the initial interpretation?','Differences in camera operation may affect the counts',['The animals cannot be photographed in winter','Every camera recorded continuously','The survey was designed to count plants'],'What will the man calculate?','The actual operating time of the cameras',['The price of a new survey vehicle','The number of future field trips','The age of every animal photographed']),
C(`Woman: I was going to submit our joint poster tonight, but the contributor list still has my old department.\nMan: The submission form lets us update affiliations until tomorrow, even after uploading.\nWoman: Then we don’t need to hold back the whole poster?\nMan: No. Upload the current file, but fix the affiliation in the form and send me a screenshot to check.\nWoman: I’ll make that correction before confirming the submission.`, 'What needs correcting?','The woman’s departmental affiliation',['The poster’s research results','The submission deadline','The names of all contributors'],'What will she do before confirming?','Update the form and obtain a check of the correction',['Withdraw the poster permanently','Wait until after the correction deadline','Remove her name from the project']),
C(`Man: The guest speaker’s train arrives later than planned. She’ll miss the first part of the event.\nWoman: Could we start with the student demonstrations instead of her talk?\nMan: Those presenters are ready, and the audience can still ask her questions afterward.\nWoman: Then we should change the running order rather than shorten everything. I’ll tell the hosts and put an update by the entrance.\nMan: I’ll confirm the new talk time with her.`, 'What has caused the need for a change?','The guest speaker will arrive later than expected',['The audience has asked to cancel questions','The student presenters have not prepared','The event venue has closed'],'What solution do the speakers choose?','Reorder the activities',['Cancel the student demonstrations','Begin the talk without the speaker','Remove every question period']),
C(`Woman: The library guide recommends using several search terms, but my first search already gives hundreds of results.\nMan: More results don’t necessarily mean better coverage. Have you checked whether the main terms in your topic are used differently across fields?\nWoman: Not yet.\nMan: Try a few alternative terms, then compare which useful papers each search finds.\nWoman: I’ll keep a search log so I can explain the choices in my methods section.`, 'What does the man suggest about the number of results?','A large total does not ensure that the search finds the most relevant work',['A search with many results should never be changed','Alternative terms always produce identical papers','Only one discipline should be consulted'],'What will the woman record?','The searches she tries and the reasons for her choices',['Only the number of pages in each paper','The library’s opening hours','A list of papers she has not located'])
];
const A=(script,q1,a1,d1,q2,a2,d2)=>({script,qs:[Q(q1,a1,...d1,'The announcement states the relevant condition or reason.'),Q(q2,a2,...d2,'The instruction or implication follows from the stated arrangement.')]});
export const announcements=[
A(`Before you leave, a reminder about tomorrow’s archive visit. Meet at the west entrance at ten, not at the reading-room desk. The archivist will take us through the storage area first. Please leave large bags in the lockers. You may photograph the sample documents shown during the workshop, but other material requires separate permission.`, 'Where should the class meet?','At the west entrance',['At the reading-room desk','Inside the storage room','Beside the bus station'],'What may students photograph without separate permission?','The workshop’s sample documents',['Every document in storage','Visitors’ identification cards','All material in the reading room']),
A(`The stream-monitoring trip will go ahead tomorrow, but the lower footbridge remains closed. We’ll begin at the upstream station and approach the second site from the road. Allow an extra fifteen minutes for the walk. If you borrowed measuring equipment, bring it to the laboratory tonight so we can check the complete set before departure.`, 'What has changed?','The route used to reach a survey site',['The day of the trip','The number of monitoring stations','The requirement to measure the stream'],'Why should equipment be returned tonight?','So the full set can be checked before departure',['So students can purchase it','Because the laboratory will permanently close','Because measuring is no longer required']),
A(`For those submitting display labels, the draft deadline is now Thursday at noon. That gives the accessibility team time to review the text before printing. Please submit editable files, not photographs of your pages. Labels should identify replicas clearly. If your object is not an original, put that information near the beginning rather than only in a footnote.`, 'Why must drafts arrive by Thursday noon?','They need review before printing',['Visitors will choose the winning label that afternoon','The objects will be sold on Friday','Photographs cannot be taken after Thursday'],'What format is requested?','An editable text file',['A photograph of a printed page','A handwritten label attached to the object','A final poster that cannot be revised']),
A(`The community history workshop has moved from Room 6 to the ground-floor meeting room because the lift is unavailable. The starting time is unchanged. Bring any photographs you want help identifying, but please don’t remove them from fragile albums. We have equipment for photographing album pages safely, and staff will explain how to use it.`, 'Why was the room changed?','To maintain access while the lift is unavailable',['To accommodate a larger projector','Because the workshop will start earlier','Because photographs are prohibited upstairs'],'What should participants do with fragile albums?','Keep the photographs inside them',['Cut the photographs out before arriving','Leave all albums at reception permanently','Separate every page for scanning']),
A(`The botanical garden needs volunteers for a seed-cleaning session on Sunday. No previous experience is required. We’ll begin with a demonstration, then work in small groups indoors. Please register so we can prepare enough workstations. Outdoor collection has been postponed because the seeds at the field site are not mature enough yet; this session uses material collected earlier.`, 'Why is outdoor collection postponed?','The seeds are not ready to collect',['Too few volunteers own outdoor shoes','The indoor room is closed','The earlier material has been lost'],'What should interested volunteers do?','Register before the session',['Bring their own seed-cleaning machines','Complete an advanced botany course','Collect immature seeds independently']),
A(`The tree-survey briefing will start at nine tomorrow in the courtyard. If rain is heavy, check your university email before leaving home; we’ll announce any indoor replacement there by eight. Please don’t assume that light rain means cancellation. Waterproof notebooks are available, but bring a pencil. Your group leader will distribute the identification guides at the briefing.`, 'How will a major weather-related change be announced?','By university email',['Through a printed letter delivered tomorrow','Only at the courtyard after nine','Through the identification guide'],'What should volunteers bring themselves?','A pencil',['A waterproof notebook','A tree-identification guide','A printed cancellation notice']),
A(`The repair café’s afternoon places are full, but there are still morning appointments. Please describe your item when booking. We can help diagnose small household products, but we cannot accept damaged batteries. Instruction is free; parts, when available, are charged at cost. Booking an appointment does not guarantee that an item can be repaired, so don’t buy replacement parts in advance.`, 'What is true of available appointments?','Some morning places remain',['Every session is full','Only afternoon places remain','No booking is needed'],'What should participants avoid doing?','Purchasing parts before the item is assessed',['Describing the item when booking','Choosing a morning appointment','Asking for a diagnosis']),
A(`Our market observation project begins Saturday. Please observe from the public seating area and avoid blocking stalls. We’re recording patterns of movement, not identifying individual shoppers, so don’t take close-up photographs of people. After thirty minutes, move to your second assigned position. Comparing the same interval at two locations will help us distinguish location effects from changes over the morning.`, 'What kind of information is the project collecting?','Patterns of movement through the market',['The names of individual shoppers','The private earnings of stallholders','Close-up portraits of every visitor'],'Why will observers move to a second location?','To make a comparison across positions',['To follow particular shoppers home','To help vendors move their stalls','To extend every observation indefinitely']),
A(`The equipment desk is introducing a new return procedure for audio recorders. Before handing one back, copy your own files and confirm that the transfer worked. Staff will then clear the card before the next loan. Do not delete files that belong to someone else. If you find any, tell the desk assistant so the previous borrower can be contacted.`, 'What should borrowers check before returning a recorder?','That their files were copied successfully',['That the next borrower has booked an interview','That every earlier file has been erased by them','That the recording card is permanently removed'],'What should they do about another person’s files?','Notify a staff member',['Upload them to the class website','Delete them without asking','Keep the recorder until the owner appears']),
A(`The neighborhood exhibition will open at two rather than noon on Friday. Installation is taking longer because the borrowed display cases arrived late. Ticket holders for the earlier slot can enter at any time after two or request a refund. The evening discussion will still begin at six. Please use the updated entry time when inviting guests; the older posters have not all been replaced yet.`, 'Why is the opening delayed?','Installation was affected by a late delivery',['The evening speaker has cancelled','All tickets have been refunded','The exhibition has moved to another city'],'Which event keeps its original time?','The evening discussion',['The noon admission slot','The first installation session','The arrival of the display cases']),
A(`Tomorrow’s podcast workshop will focus on editing, so bring a short recording rather than a written script alone. A two-minute conversation is sufficient. Obtain the speaker’s permission before recording and avoid including private information. If you cannot make a recording, download the practice file linked in the course portal. The workshop computers already have the editing software installed.`, 'What material should participants bring?','A short audio recording',['Only a printed script','Their own desktop computer','A list of software prices'],'What is offered to someone without a recording?','A downloadable practice file',['An exemption from every workshop activity','Permission to record strangers without asking','A private-information collection form']),
A(`The statistics help desk will operate in the library foyer during assessment week. You do not need an appointment, but bring your assignment instructions and the work you have attempted. Tutors can explain methods and help you interpret feedback. They will not complete assessed answers for you. At busy times, sessions will be limited to fifteen minutes so that more students can receive help.`, 'What should students bring?','Their instructions and attempted work',['A completed application for a paid appointment','Only the tutor’s email address','Another student’s finished answers'],'Why might sessions be shortened?','To allow more students to receive support',['To replace all scheduled statistics classes','To prevent students from asking about methods','To make room for an unrelated exhibition']),
A(`The community interview project is changing its file-naming procedure. Use the participant code and interview date, not the person’s name. Keep the code list in the restricted folder. This will make recordings easier to organize without exposing identities in shared filenames. Existing files should be renamed only after you have recorded the change in the project log.`, 'What is the reason for the new procedure?','To organize files while protecting participant identities',['To remove the need for interview dates','To let everyone view the restricted code list','To replace audio files with written names'],'What must happen before existing files are renamed?','The change must be recorded in the log',['The original recording must be deleted','The participant’s name must be published','The shared folder must be made public']),
A(`The meadow visit on Wednesday includes uneven ground and a short walk through wet grass. Wear sturdy shoes. We will observe the restoration plots without collecting plants. Anyone needing an alternative route should contact me today; the grounds team can arrange access from the service path. The lecture afterward is in our usual room, and attendance there does not require joining the field walk.`, 'What will students do at the plots?','Observe without collecting plants',['Remove all flowering species','Plant trees along the service path','Collect samples for private gardens'],'Who should contact the speaker today?','Students who need an alternative access route',['Everyone planning to attend the later lecture','Only students who own wet-weather equipment','Students who want the usual classroom changed']),
A(`For the catalogue project, please keep both the original subject label and your proposed alternative in the worksheet. We need to understand the relationship between them before changing the public record. Add a brief reason for each proposal. Do not overwrite the shared catalogue directly. The librarian will review the complete list with us at next week’s session.`, 'Why should both labels be retained in the worksheet?','Their relationship must be reviewed before a change',['The public catalogue cannot display any subject labels','Students are being asked to translate every title','The original records have already been removed'],'What should students avoid?','Changing the shared catalogue directly',['Explaining their proposed alternatives','Discussing labels with the librarian','Keeping the original terminology in the worksheet']),
A(`The model-building session has been divided into two groups because each participant needs table space. Check the portal for your assigned time. You may exchange sessions with another student if you notify the instructor first. Please don’t simply attend the other session, since both are already at capacity. All materials will be provided at the start of your own group’s session.`, 'Why are there two groups?','Available working space limits each session’s size',['The two groups are studying different subjects','Half the materials have been lost','One instructor refuses to teach in the morning'],'What is required to change sessions?','Arrange an exchange and notify the instructor',['Attend whichever session is more convenient','Buy a second set of materials','Wait until both sessions have finished']),
A(`The tool library will close its returns desk at four on Friday for a safety inspection. Please return borrowed equipment by then or use the staffed desk Saturday morning. Do not leave tools outside the locked door. We cannot accept them through the book-return slot, even if they fit. Loan penalties will be suspended overnight because of the early closure.`, 'Why will the desk close early?','A safety inspection is scheduled',['Every borrowed tool has been returned','The building is being sold','The library has stopped lending permanently'],'What may a borrower do without an overnight penalty?','Return equipment at the staffed desk Saturday morning',['Leave tools outside the locked door','Push tools through the book-return slot','Keep equipment until the following month']),
A(`Our visitor survey will include both weekday and weekend sessions. Earlier plans covered only Saturday, which might have missed people who use the garden differently during the week. Please sign up for one shift of each type if possible. We will use the same questions in both sessions so that responses can be compared without changes in wording affecting the results.`, 'Why are weekday sessions being added?','To include visitors absent from a Saturday-only survey',['To avoid interviewing anyone on weekends','To replace the garden’s weekday opening hours','To test a completely different set of questions'],'Why will question wording remain the same?','To make comparisons less affected by wording changes',['To prevent respondents from expressing opinions','To shorten every visit to the garden','To ensure that the same people attend twice']),
A(`The dune field trip starts from the coastal visitor centre at ten. Stay on the marked boardwalk until the guide identifies an area where observation is permitted. Some plants are easily damaged even when the sand around them looks bare. We will discuss both stable and moving dunes; the purpose is to understand the habitat, not to collect sand or vegetation.`, 'Why must the group initially stay on the boardwalk?','To avoid damaging vulnerable vegetation',['To ensure everyone collects the same sand sample','Because moving dunes contain no organisms','Because the guide is unavailable until noon'],'What is the trip’s purpose?','To study how the dune habitat works',['To stabilize every moving dune','To remove plants from observation areas','To build a new coastal road']),
A(`The photography demonstration has been moved to the engineering studio, where we can control the lighting. Please arrive before the door sign changes to Recording. Once the sequence begins, opening the door would alter the light and interrupt the experiment. Anyone arriving late can watch the recorded demonstration afterward in the course portal. There will be a separate question period at the end.`, 'Why is late entry restricted?','Opening the door would disturb the controlled lighting',['Late students must buy a recording ticket','The studio cannot contain any observers','The question period begins before the experiment'],'How can a late arrival catch up?','View the recording in the course portal',['Repeat the experiment alone in the studio','Ask the class to restart immediately','Enter whenever the sign says Recording']),
A(`The bridge inspection talk will include a short outdoor demonstration. We will not cross the closed bridge. The engineer will use a small model in the visitor area to show how expansion joints work. Bring a jacket, since that part takes place outside. The following discussion will be indoors, where photographs of the actual inspection will be shown.`, 'How will expansion joints be demonstrated?','With a small model in the visitor area',['By allowing students onto the closed bridge','By removing a joint from the actual structure','With a written quiz only'],'What is implied about the inspection photographs?','Students can see them during the indoor discussion',['They will replace the outdoor model demonstration entirely','Students must take them while crossing the bridge','They are unavailable because the bridge is closed']),
A(`The memory study needs participants for two brief sessions one week apart. You must be available for both; attending the first alone will not provide the comparison we need. No special preparation is required. Please do not practice the word list between sessions unless the researcher explicitly asks you to do so. Sign up through the psychology department’s participant portal.`, 'Why must participants attend twice?','The research requires a comparison across the two sessions',['The first meeting is only a payment appointment','The same lecture is repeated for convenience','Participants must bring a different friend each time'],'What are participants asked not to do independently?','Practice the study’s word list between sessions',['Use the registration portal','Attend the second session','Ask about the study instructions']),
A(`The food-history seminar will meet in the teaching kitchen this week. We will examine preservation methods but will not taste the historical samples, which are for demonstration only. Bring the reading notes from last week. Students with access requirements should contact the course office; the side entrance provides a step-free route, but staff need advance notice to unlock it.`, 'Why should students not taste the samples?','They are intended only for demonstration',['They have been reserved for the course office','The seminar is about photography instead','Every student must prepare a personal recipe'],'Why is advance contact requested for step-free access?','Staff must unlock the appropriate entrance',['The kitchen has no accessible entrance','Students must attend a different course','The main reading notes must be replaced']),
A(`For the flower-timing project, observations should be entered on the day they are made. If you miss a day, leave that entry blank rather than estimating from memory. We can work with missing observations when they are clearly marked. An invented date, however, could look like genuine evidence and distort our interpretation. Include the plant’s identification number with every entry.`, 'What should observers do about a missed day?','Leave a clearly missing entry',['Estimate the date without labeling it','Copy another plant’s observation','Enter the next day’s value twice'],'Why is estimating from memory discouraged?','It could be mistaken for an actual observation',['Memory entries are always more detailed','The project records only weather conditions','The identification numbers would become unnecessary']),
A(`The map-design review is now online rather than in the studio. Upload your map and its legend by Thursday evening. We will view all submissions on the same screen size during the session, so check that important labels remain readable when the map is reduced. Keep the original editable file as well; you may need to revise the display after receiving feedback.`, 'What should students check before submission?','Whether labels remain readable at a smaller display size',['Whether the legend can be removed completely','Whether every map uses identical colors','Whether the original file has been deleted'],'Why should they retain an editable file?','To make revisions after the review',['To avoid submitting any map this week','To replace the need for a legend','To prevent anyone from giving feedback'])
];
